    // Entity equality is by Id (wave-2 review item #15). EF Core tracks
    // entities by Id within a single context, but cross-context
    // comparisons (e.g. the alert service comparing a freshly-loaded
    // entity to a request DTO's projected copy) need reference equality
    // to work. Using Id as the equality key means two distinct references
    // to the same row compare equal.
    public override bool Equals(object? obj) => obj is Alert other && Id == other.Id;

    public override int GetHashCode() => Id.GetHashCode();

    // Entity equality is by the composite key (wave-2 review item #15).
    public override bool Equals(object? obj) =>
        obj is AlertChannelMode other && AlertId == other.AlertId && ChannelId == other.ChannelId;

    public override int GetHashCode() => HashCode.Combine(AlertId, ChannelId);

namespace SonrisaNews.Domain.Alerts;

/// <summary>
/// Filter shape for a <see cref="Entities.Alert"/> of type <c>Market</c>.
/// Defines a list of ticker symbols and a percent-change threshold over a
/// rolling window. The matcher (wave 7) evaluates each new quote against
/// this shape.
/// </summary>
/// <param name="Symbols">
/// Non-empty list of ticker symbols (e.g. <c>AAPL</c>, <c>MSFT</c>). At
/// least one symbol is required.
/// </param>
/// <param name="PercentThreshold">
/// The minimum absolute percent change in <paramref name="WindowMinutes"/>
/// to fire the alert. Must be a positive finite value.
/// </param>
/// <param name="WindowMinutes">
/// The rolling window in minutes over which the percent change is
/// measured. Must be a positive integer.
/// </param>
public sealed record MarketAlertFilters(
    IReadOnlyList<string> Symbols,
    double PercentThreshold,
    int WindowMinutes);

namespace SonrisaNews.Domain.Alerts;

/// <summary>
/// Filter shape for a <see cref="Entities.Alert"/> of type <c>Disaster</c>.
/// A disaster event has a region (country or US-state code), an event type
/// (earthquake, hurricane, …), and a severity score. The matcher
/// (wave 8) drops events that fail any of these conditions.
/// </summary>
/// <param name="Regions">
/// Non-empty list of region codes — ISO 3166-1 alpha-2 for countries
/// (e.g. <c>"JP"</c>) or US state codes (e.g. <c>"US-CA"</c>). The
/// <c>"global"</c> sentinel means "any region". The list is OR-matched.
/// </param>
/// <param name="EventTypes">
/// Non-empty list of disaster event types (e.g. <c>"earthquake"</c>,
/// <c>"hurricane"</c>, <c>"flood"</c>). The list is OR-matched.
/// </param>
/// <param name="MinSeverity">
/// The minimum severity score to fire the alert. Scale is per event type
/// (Richter magnitude for earthquakes, Saffir-Simpson category for
/// hurricanes, etc.). Must be a non-negative finite value.
/// </param>
public sealed record DisasterAlertFilters(
    IReadOnlyList<string> Regions,
    IReadOnlyList<string> EventTypes,
    double MinSeverity);

namespace SonrisaNews.Domain.Alerts;

/// <summary>
/// How a list of keywords is matched against an event's title or content.
/// Used by <see cref="NewsAlertFilters"/>.
/// </summary>
public enum KeywordMatchMode
{
    /// <summary>All keywords must be present (logical AND).</summary>
    All = 1,

    /// <summary>Any keyword is enough (logical OR).</summary>
    Any = 2,
}

namespace SonrisaNews.Domain.Alerts;

/// <summary>
/// Filter shape for a <see cref="Entities.Alert"/> of type <c>News</c>.
/// Stored as the <c>Filters</c> JSON column on the alert; the JSON keys
/// are stable and are the contract between the backend and the
/// frontend's alert editor.
/// </summary>
/// <param name="SourceIds">
/// Optional list of <c>Source.Id</c> values to scope the alert to. Null or
/// empty = match against every enabled news source.
/// </param>
/// <param name="Keyword">
/// Optional single keyword matched against the event title or summary.
/// Null = no keyword filter.
/// </param>
/// <param name="MatchMode">
/// How <paramref name="Keyword"/> is interpreted. Only meaningful when
/// <paramref name="Keyword"/> is non-null. Defaults to <see cref="KeywordMatchMode.All"/>
/// (kept for forward compatibility — a future wave may allow a list of
/// keywords with the same mode).
/// </param>
/// <param name="Tags">
/// Optional list of free-form tags matched against the event's tag set.
/// Null or empty = no tag filter.
/// </param>
public sealed record NewsAlertFilters(
    IReadOnlyList<Guid>? SourceIds,
    string? Keyword,
    KeywordMatchMode MatchMode,
    IReadOnlyList<string>? Tags);

