    private static CreateAlertInput NewCreateInput(string name, AlertType type, string filters) =>
        new(Name: name, Type: type, Filters: filters);

    private static (AlertService Service, Guid UserId, SonrisaNewsDbContext Db) NewService(string? currentUserEmail = "alice@example.com")
    {
        var db = NewDbContext();
        var owner = SeedUser(db, currentUserEmail);
        var currentUser = new FakeCurrentUser(owner.Id, owner.Email);
        var clock = new FakeClock();
        var svc = new AlertService(currentUser, db, clock, NullLogger<AlertService>.Instance);
        return (svc, owner.Id, db);
    }

    private static SonrisaNewsDbContext NewDbContext()
    {
        var options = new DbContextOptionsBuilder<SonrisaNewsDbContext>()
            .UseSqlite("Data Source=:memory:")
            .Options;
        var ctx = new SonrisaNewsDbContext(options);
        ctx.Database.OpenConnection();
        ctx.Database.EnsureCreated();
        return ctx;
    }

    private static User SeedUser(SonrisaNewsDbContext db, string? email)
    {
        if (email is null)
        {
            // No current user — the AlertService must check ICurrentUser.Id
            // before doing anything, so we don't even seed a user.
            return null!;
        }

        var user = new User
        {
            Id = Guid.NewGuid(),
            Email = email,
            PasswordHash = "h",
            DisplayName = email.Split('@')[0],
        };
        db.Users.Add(user);
        db.SaveChanges();
        return user;
    }

    private static async Task<Channel> SeedChannelAsync(SonrisaNewsDbContext db, Guid userId)
    {
        var channel = new Channel
        {
            Id = Guid.NewGuid(),
            UserId = userId,
            Type = ChannelType.Email,
            Destination = $"{userId}@example.com",
        };
        db.Channels.Add(channel);
        await db.SaveChangesAsync();
        return channel;
    }

    /// <summary>Minimal <see cref="ICurrentUser"/> for tests. The AlertService only reads <c>Id</c> and <c>IsAuthenticated</c>.</summary>
    private sealed class FakeCurrentUser(Guid? id, string? email) : ICurrentUser
    {
        public Guid? Id { get; } = id;
        public string? Email { get; } = email;
        public bool IsAuthenticated => id is not null;
    }

    private sealed class FakeClock : IClock
    {
        public DateTimeOffset UtcNow { get; } = new(2026, 6, 5, 12, 0, 0, TimeSpan.Zero);
    }
