    };

    private ActionResult MapNotFound(AlertOutcome outcome) => outcome switch
    {
        AlertOutcome.NotFound => Problem(statusCode: StatusCodes.Status404NotFound, title: "Alert not found"),
        AlertOutcome.ChannelNotFound => Problem(statusCode: StatusCodes.Status404NotFound, title: "Channel not found"),
        AlertOutcome.Unauthenticated => Unauthorized(),
        // The controller's actions route InvalidFilter to BuildValidationProblem
        // and Unauthenticated to MapAuth before reaching this method. If a
        // future refactor routes a new outcome through here without
        // updating the switch, fail loudly rather than return a wrong
        // status silently.
        _ => throw new InvalidOperationException(
            $"MapNotFound: unexpected outcome {outcome}. Update the switch or route the outcome to the right mapper."),
    };"}]}

