{"filePath":"c:\Users\Lenovo\repos\SonrisaNews\backend\src\SonrisaNews.Infrastructure\Alerts\AlertService.cs","newString":"    public async Task<AlertResult<AlertChannelMode>> SetChannelModeAsync(Guid alertId, SetChannelModeInput input, CancellationToken ct)
    {
        if (currentUser.Id is not { } userId)
        {
            return AlertResult<AlertChannelMode>.Failure(AlertOutcome.Unauthenticated);
        }

        // The alert ownership check runs first; the channel ownership
        // check runs only if the alert is owned. Both probe directions
        // return NotFound (not ChannelNotFound) so a user with their
        // own channel cannot probe other users' alert ids by trying
        // random ones, AND a user with no channel cannot probe other
        // users' alert ids either — both probes are uniformly NotFound.
        var alertTask = db.Alerts.AsNoTracking().FirstOrDefaultAsync(a => a.Id == alertId && a.UserId == userId, ct);
        var channelTask = db.Channels.AsNoTracking().FirstOrDefaultAsync(c => c.Id == input.ChannelId && c.UserId == userId, ct);
        await Task.WhenAll(alertTask, channelTask);","oldString":"    public async Task<AlertResult<AlertChannelMode>> SetChannelModeAsync(Guid alertId, SetChannelModeInput input, CancellationToken ct)
    {
        if (currentUser.Id is not { } userId)
        {
            return AlertResult<AlertChannelMode>.Failure(AlertOutcome.Unauthenticated);
        }

        // The alert AND the channel must both be owned by the caller.
        // The alert ownership check is reported first; the channel
        // ownership check is reported only if the alert is owned
        // (so a user can't probe other users' channel ids by trying
        // random alert ids).
        var alertTask = db.Alerts.AsNoTracking().FirstOrDefaultAsync(a => a.Id == alertId && a.UserId == userId, ct);
        var channelTask = db.Channels.AsNoTracking().FirstOrDefaultAsync(c => c.Id == input.ChannelId && c.UserId == userId, ct);
        await Task.WhenAll(alertTask, channelTask);"}

